window.__BUNDLE__={"generatedAt":"2026-11-02T06:45:52.925515+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-10-26","archiveCutoff":"2021-11-03","addedToday":265,"addedThisRun":265,"fetchStats":{"hf":294,"arxiv":1286,"total":1580},"freshness":{"latestPaperDate":"2026-11-02","latestPublishedDate":"2026-11-02","latestBatchCount":197,"newInLast24h":265,"newInLast48h":265},"historyTotal":29151,"topicCounts":{"Multi-Agent":3115,"Evaluation":15987,"Planning":2128,"Memory":562,"Code Agent":1167,"Interpretability":979,"Agentic RAG":1553,"Agentic Search":2077,"RL for LLM":1555,"Reasoning":7824,"Hallucination":1280,"Post-Training":3242,"Alignment":3790,"World Model":584,"Tool Use":1456,"Agent Safety":2731,"Computer Use":391,"Reflection":1042,"VLM Training":2282,"LLM Training":3759,"Fine-tuning":4525,"Multimodal Agent":169,"Agent Framework":955,"Error Attribution":187,"Data Engine":576},"count":36,"recentTotal":2067,"archiveCount":0,"archiveTotal":27084,"sources":{"hf":57,"arxiv":2010,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"tags":["Post-Training","LLM Training","VLM Training","Tool Use","Fine-tuning"],"hfUrl":"https://huggingface.co/papers/2610.40799","arxiv":"https://arxiv.org/abs/2610.40799","url":"https://arxiv.org/abs/2610.40799","pdf":"https://arxiv.org/pdf/2610.40799.pdf","source":"hf","authors":["Yijia Fan","Xilin He","Yilei Jiang","Dongming Wu","Jiaxu Wang","Xiangyu Yue"],"date":"2026-11-02","title":"CaPtain: A Pipeline for Post-Training Code-as-Policy Robot Agents","upvotes":11,"topics":["Post-Training","LLM Training","VLM Training","Tool Use","Fine-tuning","RL for LLM"],"id":"arxiv:2610.40799","abstract":"Across coding, web, and tool-use tasks, language-model agents are now routinely trained with the same recipe: supervised fine-tuning (SFT) to learn the interface, then multi-turn reinforcement learning (RL) to master it. Code-as-policy (CaP) casts robot manipulation in the same form, as the policy writes code against robot APIs and reads back the results, so the same recipe should apply. Yet existing CaP agents sidestep training: they either prompt closed frontier models or delegate manipulation to pre-trained vision-language-action models (VLAs) and high-level skills, while small open vision-language models (VLMs) fail outright. We present CaPtain, an open post-training pipeline that turns a small open VLM into a capable CaP agent, with no VLA, frontier model, or privileged state at test time. CaPtain trains and deploys the policy inside CaPtain-Harness, which exposes low-level percepti"},{"tags":["LLM Training","Tool Use","Reasoning","Fine-tuning"],"submittedDate":"2026-10-29","hfUrl":"https://huggingface.co/papers/2610.40738","arxiv":"https://arxiv.org/abs/2610.40738","url":"https://arxiv.org/abs/2610.40738","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.40738.pdf","source":"hf","authors":["Aman Tiwari","Akshay Kalkunte","Akintunde Oladipo","Jash Shah","Tara Bogavelli","Hoang Nguyen","Nishanth Madhusudhan","Vishal Juneja","Sridhar Nemala","Srinivas Sunkara","Sathwik Tejaswi Madhusudhan","Shruthan Radhakrishna","Masoud Hashemi","Kelechi Ogueji","Khalil Slimi","Saloni Mittal","Pulkit Pattnaik","Shashank Maiya","Dhruv Jhamb","Esakkivel Esakkiraja","Katrina Stankiewicz","Gabrielle Gauthier Melançon","Fanny Riols","Amit Saha","Lakshmi Sirisha Chodisetty","Nitin Aggarwal","Anil Madamala","Sagar Davasam","Segan Subramanian","Vikas Yadav","Sai Rajeswar Mudumba"],"date":"2026-11-02","title":"Apriel Voice 27B Preview: An Open Model for Speech, Reasoning, and Tool Use","upvotes":10,"topics":["LLM Training","Tool Use","Reasoning","Fine-tuning"],"id":"arxiv:2610.40738","abstract":"A capable voice assistant must do more than recognize words; it must understand requests, reason over context, sustain conversations, and act through tools. We present Apriel Voice 27B Preview, an open speech-language model that unifies these capabilities within a shared reasoning backbone while retaining text and image input modalities. Built on the post-trained Gemma 4 26B-A4B checkpoint, Apriel Voice directly processes speech and generates both responses and tool calls without requiring a separate dialogue model. We introduce a two-stage training procedure to adapt the model to speech. The first stage establishes the speech interface, while the second jointly adapts the projector and backbone through supervised fine-tuning, text replay, and source-dependent cross-entropy and forward Kullback--Leibler divergence supervision. Automatically constructed speech-conditioned dialogues provid"},{"tags":["LLM Training","Evaluation"],"submittedDate":"2026-10-30","hfUrl":"https://huggingface.co/papers/2610.42141","arxiv":"https://arxiv.org/abs/2610.42141","url":"https://arxiv.org/abs/2610.42141","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.42141.pdf","source":"hf","authors":["Shengguang Wu","Suning Huang","Cherie Ho","Ria Doshi","Hao Zhu","Serena Yeung-Levy"],"date":"2026-11-02","title":"RoboArchitect: Automating the Design of Robotic Agents with Persistent Memory","upvotes":4,"topics":["LLM Training","Evaluation"],"id":"arxiv:2610.42141","abstract":"Recent work shows that a frozen robot policy performs far better inside an agent harness, where control code decides when to query the policy, consult vision tools, or command the arm directly. Yet today these harnesses are built by hand and redesigned for each new robot or benchmark. We show that harness design can be automated, offering a strong alternative to finetuning on a novel setup. In RoboArchitect, a coding model observes a robot's rollouts, diagnoses failures, and iteratively revises the harness around the frozen policy. The harness evolves on a set of episodes for its optimization and is evaluated on held-out scenes and tasks. Without updating any model weights, RoboArchitect raises average success from 9.7% to 43.3% on unseen scenes (4.5x) and from 12.7% to 40.2% on unseen tasks (3.2x), across multiple benchmarks and policies. The gains are largest where the benchmark is far"},{"tags":["Reasoning"],"submittedDate":"2026-10-30","hfUrl":"https://huggingface.co/papers/2610.41260","arxiv":"https://arxiv.org/abs/2610.41260","url":"https://arxiv.org/abs/2610.41260","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41260.pdf","source":"hf","authors":["Yiqi Liang","Xiaodong Cun"],"date":"2026-11-02","title":"SketchDirector: Complex Scene Sketching via Agentic Layout Reasoning and Detail Refinement","upvotes":1,"topics":["Reasoning"],"id":"arxiv:2610.41260","abstract":"Existing sketch generation methods often rely on image guidance and are largely limited to individual objects or simplified scenes, leaving text-guided complex scene sketching underexplored. We present SketchDirector, an agentic framework that mimics the human sketching workflow for automatic multi-concept scene sketching. Given a scene-level text prompt, SketchDirector first employs a large language model~(LLM) to decompose the scene into multiple draft assets, where each is represented by a set of Bézier curves. Then, an agentic reasoning loop iteratively plans and executes their spatial arrangement, guided by self-evolving memory. Finally, a detail refinement module leverages diffusion priors to enhance sketch quality while preserving geometric structure. To support future research and applications in multi-concept scene sketch generation, we further introduce the \\textit{MCSketch8K} "},{"tags":["Post-Training","LLM Training","Reasoning","Planning","Evaluation"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40992","url":"https://arxiv.org/abs/2610.40992","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.40992.pdf","source":"arxiv","authors":["Junwei Wu","Runze Yan","Yuzhang Xie","Hanqi Luo","Ziwei Dong","Jiaying Lu","Xiao Hu","Carl Yang"],"date":"2026-11-02","title":"Can Personal Requirements Become Supervision for Planning?","upvotes":0,"topics":["Post-Training","LLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"id":"arxiv:2610.40992","abstract":"Managing multiple chronic conditions through diet requires satisfying disease- and medication-specific requirements jointly across meals and days while preserving established eating habits. These requirements are public in clinical guidelines and drug labels, yet turning them into a feasible plan for one person remains difficult for language-model agents. In our dietitian-approved weekly planning evaluation built from NHANES, thirteen models, from medically fine-tuned 8B models to GPT-6.1 Sol, pass fewer than 3% of complete plans through direct generation. Explicit rules, higher reasoning effort, or model-directed tools leave GPT-6.1 Sol at no more than 8%. We present Noura, which pairs LLM planning with executable personal specifications instantiated from public clinical guidance and individual health and dietary profiles. During planning, the specification grounds foods, optimizes port"},{"tags":["Error Attribution","Post-Training","Planning","Evaluation","Reflection"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41564","url":"https://arxiv.org/abs/2610.41564","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41564.pdf","source":"arxiv","authors":["Mingyang Liu","Qingcan Kang","Shixiong Kai","Tao Zhong","Mingxuan Yuan","Xin Li","Linqi Song"],"date":"2026-11-02","title":"Verify--Backtrack Loop: Structured Precondition Recovery for Long-Horizon Language Agents","upvotes":0,"topics":["Error Attribution","Post-Training","Planning","Evaluation","Reflection"],"id":"arxiv:2610.41564","abstract":"Language agents increasingly tackle long-horizon tasks in interactive environments, where actions often depend on latent preconditions. The core difficulty is not trajectory length but recovery: when a prerequisite is missing or an earlier decomposition fails, trying another plausible action rarely helps. ReAct and later reflection or adaptive-planning methods support local correction, but express recovery as free-form text, with no explicit control state linking the terminal goal, the active goal, and the failure source. We introduce the Verify--Backtrack Loop (VBL), a training-free extension of ReAct that turns precondition discovery and failure diagnosis into structured planning-state updates. VBL maintains the task decomposition as a bounded goal stack and, on goal activation, execution failure, or material state change, jointly verifies two horizons---whether the active goal contrib"},{"tags":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.42149","url":"https://arxiv.org/abs/2610.42149","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.42149.pdf","source":"arxiv","authors":["Byungwoo Jeon","Yoonwoo Jeong","Hyunseok Lee","Minsu Cho","Jinwoo Shin"],"date":"2026-11-02","title":"Latent Reasoning in Continuous Space for Unified Multimodal Models","upvotes":0,"topics":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"id":"arxiv:2610.42149","abstract":"Unified Multimodal Models (UMMs) achieve remarkable success on diverse multimodal understanding and generation tasks, yet they still struggle to effectively leverage language-based chain-of-thought reasoning for image generation. As a result, existing reasoning-augmented UMMs often fail to inherit the test-time scaling and fine-grained controllability observed in large language models. We attribute this failure to a fundamental modality mismatch: reasoning is performed in a discrete token space, whereas image generation operates in a continuous space. To bridge this gap, we introduce a Latent Reasoning framework in Continuous space (LARC), which alleviates the token-level bottleneck by reasoning over continuous hidden states. Specifically, the training framework consists of two stages: (i) curriculum supervised fine-tuning (SFT), and (ii) information-gain reinforcement learning (RL). Fir"},{"tags":["LLM Training","Evaluation","Fine-tuning","World Model"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40798","url":"https://arxiv.org/abs/2610.40798","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.40798.pdf","source":"arxiv","authors":["Zhifei Hu","Alexandra I. Cristea","Adel Bibi","Jialin Yu"],"date":"2026-11-02","title":"Beyond Plausible Prediction: Safety Sufficiency in Web World Models","upvotes":0,"topics":["LLM Training","Evaluation","Fine-tuning","World Model"],"id":"arxiv:2610.40798","abstract":"Web world models increasingly predict the consequences of candidate actions before agents act, yet a plausible predicted future does not necessarily support the correct safety decision. In a matched human evaluation of 3,000 predictions from ten frozen open models, 86.1% are judged semantically plausible. However, several models exhibit highly asymmetric authorisation behaviour, combining low false-safe execution with poor recall of clarifiable ASK cases and a strong preference for BLOCK. This motivates safety sufficiency: whether a predictive interface preserves and exposes the policy-decisive information required to distinguish actions that may be EXECUTED, require clarification through ASK, or should be BLOCKED. We introduce SafeWebWorld, a benchmark for evaluating safety sufficiency across five web-safety domains through action-conditioned futures, policy-decisive evidence, and polic"},{"tags":["LLM Training","Reasoning","Interpretability","Fine-tuning"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41754","url":"https://arxiv.org/abs/2610.41754","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41754.pdf","source":"arxiv","authors":["Yuquan Li","Xinyang Jiang","Yuhao Xue","Cairong Zhao"],"date":"2026-11-02","title":"Multimodal In-Context Learning with Explicit Rule Induction","upvotes":0,"topics":["LLM Training","Reasoning","Interpretability","Fine-tuning"],"id":"arxiv:2610.41754","abstract":"A central challenge in multimodal in-context learning (MICL) arises from tasks that are ill-defined without context and require uncovering the underlying rules from demonstrations. Existing methods predominantly treat MICL as direct input-output mapping, overlooking the importance of explicitly inducing and reasoning over such rules, limiting both performance and interpretability. We propose ERIM, Explicit Rule-Induction for Multimodal In-Context Learning, a unified framework that enhances MICL by explicitly inducing the latent rules governing demonstration samples. Leveraging the reasoning ability of multi-modal large language model (MLLM), ERIM constructs rule-centric MICL datasets, introduces explicit supervision for rule induction, and fine-tunes MLLM to perform explicit rule-induction via a two-stage training strategy that combines mixed cold-start supervised fine-tuning with reinfo"},{"tags":["LLM Training","Reasoning","Evaluation","Reflection"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41296","url":"https://arxiv.org/abs/2610.41296","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41296.pdf","source":"arxiv","authors":["Minju Gwak","Alan Ritter"],"date":"2026-11-02","title":"Self-Improvement with Auxiliary Rewards: Learning from Verified Traces and Evaluating Transfer","upvotes":0,"topics":["LLM Training","Reasoning","Evaluation","Reflection"],"id":"arxiv:2610.41296","abstract":"Answer-level rewards cannot distinguish reasoning traces with equally correct outcomes. We study whether auxiliary trajectory preferences improve small-language-model self-improvement and transfer under limited supervision. We compare confidence-based (SC) and entropy-based metrics (UID-Conj.), which combines global entropy variation and local smoothness, through online reward augmentation and offline training on correct responses. Online experiments adapt Qwen3-1.7B on 30 AIME problems without reference answers; offline experiments use historical AIME problems. UID-Conj. improves the online macro-average across the adaptation benchmark and three transfer benchmarks by 2.08 percentage points over unmodified TTRL. The strongest evidence comes from offline weighted SFT: UID-Conj. exceeds uniform weighting on the same response pool by 1.93 points, with a paired prompt-bootstrap 95\\% CI of ["},{"tags":["VLM Training","Reasoning","Evaluation","RL for LLM"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41629","url":"https://arxiv.org/abs/2610.41629","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41629.pdf","source":"arxiv","authors":["Chanseul Cho","Noori Bae","Dongheon Lee","Youngmin Ro"],"date":"2026-11-02","title":"GRIT: Gradient Masking for Visually Misgrounded Tokens in Text-Rich Reasoning","upvotes":0,"topics":["VLM Training","Reasoning","Evaluation","RL for LLM"],"id":"arxiv:2610.41629","abstract":"Reinforcement learning with verifiable rewards (RLVR) has recently been extended to vision-language models (VLMs), yet its effectiveness remains limited for text-rich reasoning tasks. We highlight a key factor contributing to this limitation: models frequently arrive at correct final answers despite misperceiving visual information during intermediate steps. We define this phenomenon as Correct-but-Visually-Misgrounded Reasoning (CVMR). Because standard RLVR rewards only final-answer correctness, it fails to differentiate between properly grounded and misgrounded reasoning, reinforcing both equally. Through token-level analysis, we reveal that CVMR tokens exhibit distinct attention patterns that differ systematically from well-grounded ones. Based on this observation, we propose GRIT, a training framework that incorporates visual grounding into RLVR to mitigate the impact of CVMR. Furthe"},{"tags":["Post-Training","LLM Training","Evaluation","RL for LLM"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40998","url":"https://arxiv.org/abs/2610.40998","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.40998.pdf","source":"arxiv","authors":["Tiejin Chen","Maunil Vyas","Huaiyuan Yao","Hua Wei"],"date":"2026-11-02","title":"Steering Vectors as a Training Signal in LLM Post-Training","upvotes":0,"topics":["Post-Training","LLM Training","Evaluation","RL for LLM"],"id":"arxiv:2610.40998","abstract":"Steering vectors (SVs) are residual-stream directions that shift the behavior of LLMs when added to hidden states at inference time. While prior work has mainly used SVs as post-hoc controls, we ask whether the same directions can also guide parameter updates during post-training. We study this question across supervised learning, including SFT and distillation, and reinforcement learning with verifiable rewards (RLVR). Our framework considers two intervention regimes: a hidden-state hook during teacher-forced supervised training, and an advantage-repair mechanism on wrong rollouts in GRPO. For each regime, we analyze three design axes, which are the steering direction, its placement, and the operation used to combine it with training. In supervised settings, SV injection improves over plain SFT and distillation, with gains scaling with the off-policy gap and reaching up to a $12\\%$ impr"},{"tags":["Reasoning","Hallucination","Reflection","RL for LLM"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.42054","url":"https://arxiv.org/abs/2610.42054","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.42054.pdf","source":"arxiv","authors":["Xiao Yu","Justin Chih-Yao Chen","Zaid Khan","Hyunji Lee","Mohit Bansal"],"date":"2026-11-02","title":"CRoS: Causality Reward on Scrambled CoTs Improves Accuracy and Reasoning Faithfulness","upvotes":0,"topics":["Reasoning","Hallucination","Reflection","RL for LLM"],"id":"arxiv:2610.42054","abstract":"Reinforcement learning with verifiable rewards (RLVR) has become the standard method for training language models to reason. However, RLVR typically relies solely on outcome correctness, which does not guarantee that the CoT causally contributes to the final answer. Without this connection, outcome rewards may fail to reinforce high-quality reasoning. Existing causality metrics assess CoT causality by perturbing the CoT, such as deleting reasoning steps or injecting errors, and measuring changes in the final answer. However, these perturbations inevitably alter information in each step. Consequently, high causality scores may reflect sensitivity to information changes introduced by perturbation rather than true causality. Such confounding effects further induce undesirable reasoning behaviors when these metrics are used as training rewards, including generating less informative CoTs and "},{"tags":["Agent Safety","Post-Training","LLM Training","Evaluation"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41998","url":"https://arxiv.org/abs/2610.41998","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41998.pdf","source":"arxiv","authors":["Sizhe Chen","Yibo Peng","Jaewon Chang","Chawin Sitawarin","David Wagner"],"date":"2026-11-02","title":"SecPO: Principled Adversarial Training for Prompt Injection Security","upvotes":0,"topics":["Agent Safety","Post-Training","LLM Training","Evaluation"],"id":"arxiv:2610.41998","abstract":"Recognized as a top threat to AI agents, prompt injection allows instructions from untrusted data (email, documents, websites) to manipulate the agent's operation. The existing best-defended LLM, Meta-SecAlign, is trained with the DPO loss but still suffers from attack success rates (ASRs) approaching 100% under adaptive prompt injections. One reason is that DPO anchors the model around the undefended reference model, which is insecure. We show an idealized reference model---an injection-invariant, utility-preserving oracle---can nevertheless be approximated, as its output distribution in training is interestingly accessible. This new observation motivates a theoretically principled SecPO loss. Another Meta-SecAlign shortcoming is that it trains on weak simulated attacks. We implement an efficient adversarial training (AT) pipeline that synthesizes strong injected inputs (best@240), and "},{"tags":["VLM Training","Reasoning","Evaluation","Alignment"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41618","url":"https://arxiv.org/abs/2610.41618","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41618.pdf","source":"arxiv","authors":["Chanseul Cho","Jaesung Jun","Dongheon Lee","Youngmin Ro"],"date":"2026-11-02","title":"Attention Maps Know When to Think: Training-Free Difficulty-Aware Chain-of-Thought for Reasoning Segmentation","upvotes":0,"topics":["VLM Training","Reasoning","Evaluation","Alignment"],"id":"arxiv:2610.41618","abstract":"Chain-of-Thought (CoT) prompting has become a standard reasoning strategy in Multi-modal Large Language Models (MLLMs), showing strong performance in complex vision-language tasks such as reasoning segmentation. However, our analysis reveals that indiscriminate CoT usage can lead to degraded performance by inducing unnecessary reasoning, a phenomenon we term overthinking. In reasoning segmentation, overthinking often leads to misalignment between the query's intent and visual grounding. To address this, we propose Difficulty-Aware Chain-of-Thought (DA-CoT), a training-free adaptive framework that selectively triggers CoT based on the input's intrinsic difficulty. We find that the entropy of the model's attention maps reliably reflects task difficulty: low entropy indicates confident, localized grounding, while high entropy suggests uncertainty and potential benefit from CoT. DA-CoT uses "},{"tags":["Post-Training","LLM Training","Reasoning","RL for LLM"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40726","url":"https://arxiv.org/abs/2610.40726","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.40726.pdf","source":"arxiv","authors":["Zichen Bai","Yanli Wang","Yang Liu","Junhao Shi","Xueqin Liu","Jinguo Sun","Muye Li","Shaoqiang Zheng","Xuefei Diao","Zhuwei Zeng","Nan Duan","Peng Cao"],"date":"2026-11-02","title":"Li$^{2}$SAO: Lifting Light Singl-Rollout Asynchronous RL Optimization via Group-Relative Actor-Critic Bootstrapping","upvotes":0,"topics":["Post-Training","LLM Training","Reasoning","RL for LLM"],"id":"arxiv:2610.40726","abstract":"Asynchronous reinforcement learning (RL) is becoming a mainstream paradigm for post-training large language models (LLMs), as it improves training efficiency by updating the model as rollouts arrive. Recent work argues that group-wise sampling in GRPO does not naturally fit asynchronous RL training because rollout lengths follow a long-tailed distribution, and proposes Single-rollout Asynchronous Optimization (SAO) to improve stability and off-policy behavior, especially on agentic tasks. However, SAO relies on a closed-source value model obtained from scaling value pretraining. In this paper, we analyze GRPO and LiSAO, our lightweight reproduction of SAO without the pretrained value model, on single-turn reasoning and multi-turn agentic tasks. We find that GRPO outperforms LiSAO on reasoning tasks, while the reverse holds on agentic tasks. Since the value model of LiSAO is not yet well "},{"tags":["Reasoning","Planning","Evaluation","Data Engine"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41704","url":"https://arxiv.org/abs/2610.41704","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41704.pdf","source":"arxiv","authors":["Minh-Nam Tran","Abulhair Saparov"],"date":"2026-11-02","title":"GraphNIAH: A Benchmark for Long-Context Reasoning over Real-World Graphs","upvotes":0,"topics":["Reasoning","Planning","Evaluation","Data Engine"],"id":"arxiv:2610.41704","abstract":"The needle-in-a-haystack (NIAH) benchmark was introduced as a test for measuring a model's ability to find small relevant facts within a very large body of input text. However, existing NIAH benchmarks each suffer from one or more of the following limitations: (1) reliance on synthetic data, so their evaluations may not generalize to real-world settings; (2) reuse of previously published datasets, leading to the risk of benchmark contamination; (3) dependence on manual annotation, which requires human effort to create and update data and is prone to future benchmark contamination; and (4) unrealistic simplification of long-context multi-hop reasoning where each next step is trivial given previous steps, while real-world reasoning often requires planning over multiple possible proof paths. To address these limitations, we introduce \\Benchmark, a dynamic benchmark built from real citation "},{"tags":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41769","url":"https://arxiv.org/abs/2610.41769","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41769.pdf","source":"arxiv","authors":["Dicong Yu","Wenhua Wang","Tian Wang"],"date":"2026-11-02","title":"Stepwise-Querying: Distilling Reasoning without Access to Teacher Chain-of-Thought","upvotes":0,"topics":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"id":"arxiv:2610.41769","abstract":"Reasoning distillation is widely used to transfer the reasoning capabilities of large language models to smaller students through teacher-generated supervision. In the black-box setting, however, teachers may expose only final answers and brief solutions, leaving intermediate calculations and validity conditions unavailable and thus limiting the reasoning supervision available for distillation. We propose Stepwise Querying, which elicits step-specific explanations without requiring access to the teacher's internal chain-of-thought (CoT) traces. Independent queries to the same teacher request intermediate derivations, validity checks, and corrections for individual steps, the assembled solutions are then used for standard supervised fine-tuning. Across two teachers, two students, and four mathematics and code benchmarks, our method achieves the highest score in 14 of 16 comparisons with t"},{"tags":["Agent Safety","Post-Training","Evaluation","RL for LLM"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40926","url":"https://arxiv.org/abs/2610.40926","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.40926.pdf","source":"arxiv","authors":["Jialin Song","Xiaodong Liu","Weiwei Yang","Mingqian Feng","Chengquan Guo","Qiyao Ma","Carolyn Buractaon","Anson Ho","Wuyang Chen","Christopher White"],"date":"2026-11-02","title":"CoFiBreak: A Coarse-to-Fine Diversity Reward for Effective Multi-Turn Jailbreak","upvotes":0,"topics":["Agent Safety","Post-Training","Evaluation","RL for LLM"],"id":"arxiv:2610.40926","abstract":"Automated red teaming trains an attacker large language model (LLM) to elicit harmful responses from a victim LLM, but reinforcement learning can collapse attackers onto a narrow set of prompts when attack success is the only reward. Such a collapse of attack diversity can bias safety evaluation toward repeatedly testing near-duplicate attack patterns rather than the underlying harmful intents. Existing methods often trade off attack success or inference cost for greater content or strategy diversity. We propose CoFiBreak, a coarse-to-fine diversity reward for Group Relative Policy Optimization (GRPO) that improves attack diversity while preserving strong attack effectiveness and low inference cost. The coarse reward broadens which strategies the attacker uses by encouraging strategies underrepresented within each GRPO group, while the fine reward broadens how those strategies are realiz"},{"tags":["Multi-Agent","Evaluation","Alignment","Agent Framework"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41159","url":"https://arxiv.org/abs/2610.41159","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41159.pdf","source":"arxiv","authors":["Zhongnan Shi","Keyang Zhou","Siyi Li","Qichao Ying","Xinchen Ma","Shuyi Gong","Wei Tang","Sheng Li","Zhenxing Qian"],"date":"2026-11-02","title":"MATS: A Multi-Agent Framework for Controllable and Reflective Tumor Synthesis","upvotes":0,"topics":["Multi-Agent","Evaluation","Alignment","Agent Framework"],"id":"arxiv:2610.41159","abstract":"Synthesizing realistic tumors on medical images helps address data scarcity for clinical AI. Existing diffusion-based methods, however, lack fine-grained attribute-level controllability, closed-loop quality verification, and awareness of which morphological patterns are underrepresented in the target distribution. We present MATS, a multi-agent framework for text-controllable, cross-organ tumor synthesis. Given a target disease, MATS first profiles its morphological distribution over a fine-grained attribute space covering tumor geometry and appearance, and constructs a generation plan that amplifies underrepresented subtypes while keeping common ones dominant. It then localizes the target organ, proposes anatomically valid placement, and executes two-stage diffusion to produce the tumor mask and render texture, each conditioned on the corresponding attributes. A closed-loop reflective m"},{"tags":["VLM Training","Reasoning","Evaluation","Reflection"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41389","url":"https://arxiv.org/abs/2610.41389","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41389.pdf","source":"arxiv","authors":["Xiwei Liu","Yulong Li","Xinling Zhuang","Xuhui Li","Yichen Li","Haolin Yang","Zhixiang Lu","Yutong Xie"],"date":"2026-11-02","title":"Parse Before You Execute: Efficient Spatial Reasoning with Executable Primitives","upvotes":0,"topics":["VLM Training","Reasoning","Evaluation","Reflection"],"id":"arxiv:2610.41389","abstract":"Spatial reasoning in Vision-Language Models (VLMs) has increasingly benefited from tool-integrated pipelines that ground computation in explicit geometry. However, existing systems often compile queries into relatively open-ended artifacts, such as code, task constraints, tool plans, or gathered evidence, leaving what must be resolved before execution under-specified. This can lead to unnecessary tool acquisition and iterative refinement, while still producing plausible reasoning traces from incomplete spatial commitments. We identify this failure mode as under-committed query compilation. To address it, we propose PEPS, a training-free agentic paradigm Parsing Executable Primitives for Spatial reasoning under a typed FESM schema over Frame, Entity, State, and Metric. PEPS follows a parse-before-execute principle: the Parser commits each query to a compact set of executable requirements;"},{"tags":["LLM Training","Reasoning","Evaluation","Alignment"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41257","url":"https://arxiv.org/abs/2610.41257","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41257.pdf","source":"arxiv","authors":["Zhongyuan Bao","Cunjie He","Lejun Zhang","Zenglin Xu","Yanwei Fu"],"date":"2026-11-02","title":"ReVEAL: Eliciting Role-Aware Latent Visual Evidence from MLLMs for Reasoning Video Object Segmentation","upvotes":0,"topics":["LLM Training","Reasoning","Evaluation","Alignment"],"id":"arxiv:2610.41257","abstract":"Reasoning video object segmentation (ReVOS) requires segmenting the target specified by an implicit query throughout a video. Existing MLLM-based methods typically require costly cross-model alignment, tying MLLM training to a downstream segmentation model. We present ReVEAL, a decoupled thinking-with-video framework for ReVOS that elicits role-aware latent visual evidence from MLLM reasoning to directly guide segmentation. ReVEAL introduces Visual Evidence Tokens (VETs) into video reasoning to associate necessary visual regions or entities with target, background, or distractor roles, while a Dynamic Attention Layer Router adaptively aggregates VET-to-video attention across layers into role-specific grounding evidence. We train the MLLM to perform VET-augmented reasoning on our constructed ReVEAL-47K dataset, with a Contrastive Attention Grounding Loss as auxiliary supervision to apply "},{"tags":["VLM Training","Evaluation","Alignment","Fine-tuning"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41254","url":"https://arxiv.org/abs/2610.41254","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41254.pdf","source":"arxiv","authors":["Brian Tang","Kang G. Shin"],"date":"2026-11-02","title":"Hawkeye: Reading Illegible Text with Vision Language Models","upvotes":0,"topics":["VLM Training","Evaluation","Alignment","Fine-tuning"],"id":"arxiv:2610.41254","abstract":"While modern Vision-Language Models (VLMs) have been remarkably successful in general scene text recognition, they consistently struggle with the long-tail distribution of text that is degraded by motion blur or low resolution. These limitations are particularly apparent in egocentric applications like smart glasses, where text is often captured in noisy environments. In this paper, we introduce the \\textbf{BSTRB} (Blurry Scene Text Recognition Benchmark), a novel benchmark of 8,398 noisy image samples with high-fidelity annotations derived from 1,699 real-world video sequences. To support this, we present \\textbf{Hawkeye}, a VLM fine-tuned on BSTRB to read and reason about illegible text by leveraging contextual priors and pixel-level alignment. Our results show that \\name matches much larger VLMs on BSTRB overall and exceeds them on text at or below 20 pixels, in a single pass suited t"},{"tags":["VLM Training","Reasoning","Evaluation","Reflection"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41651","url":"https://arxiv.org/abs/2610.41651","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41651.pdf","source":"arxiv","authors":["Hao Yin","Tianchen Guo","Heming Du","Yan Ke","Yanbin Liu","Xin Yu"],"date":"2026-11-02","title":"When Depth Lies: Benchmarking Vision-Language Models on Mirror-Induced RGB-D Ambiguity","upvotes":0,"topics":["VLM Training","Reasoning","Evaluation","Reflection"],"id":"arxiv:2610.41651","abstract":"Vision-language models (VLMs) have made significant progress in spatial reasoning, particularly by integrating RGB images with depth data, which is often assumed to faithfully reflect physical distances. However, mirrors violate this assumption: they distort depth readings while reproducing object appearances, making reflections difficult to distinguish from real objects. As existing benchmarks rarely consider such reflective scenarios, VLM performance in mirror scenes remains largely unexplored. In this work, we introduce a mirror-centric RGB-D dataset from reflective scenes to evaluate the spatial reasoning capabilities of state-of-the-art VLMs in these scenarios. Specifically, we collect 1,011 RGB-D images from 525 real-world scenes, spanning diverse indoor and outdoor environments, six reflective surface types, and both daytime and nighttime conditions. All images are annotated with "},{"tags":["VLM Training","Reasoning","Evaluation","Fine-tuning"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40801","url":"https://arxiv.org/abs/2610.40801","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.40801.pdf","source":"arxiv","authors":["Jiahe Wu","Bing Cao","Xingyue Guo","Ruipu Zhao","Beiming Yu","Jiekang Feng","Qinghua Hu","Pengfei Zhu"],"date":"2026-11-02","title":"Drone-PUR: From Visual Clue Discovery to Understanding and Reasoning in UAV Scenes","upvotes":0,"topics":["VLM Training","Reasoning","Evaluation","Fine-tuning"],"id":"arxiv:2610.40801","abstract":"The reasoning capabilities of vision-language models (VLMs) can be limited by incomplete or inaccurate visual observations in the general domain. In unmanned aerial vehicle (UAV) scenes, small targets, subtle attributes, and changing viewpoints further complicate perception and understanding. Therefore, we introduce Drone-PUR, a dataset and benchmark organized around visual clue discovery, interpretation, and integration, corresponding to the three capability dimensions of perception, understanding, and reasoning. Reasoning samples are designed to require models to combine multiple visual clues to derive visually grounded conclusions. Its 11 tasks provide 175k training and 20k test samples spanning single images, image sequences, cross-modal images, and multiple viewpoints. All test samples undergo human review. Evaluating 22 general-purpose VLMs reveals persistent limitations in spatial"},{"tags":["VLM Training","Reasoning","Evaluation","Reflection"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41216","url":"https://arxiv.org/abs/2610.41216","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41216.pdf","source":"arxiv","authors":["Kehong Gong","Xiaoxu Zheng","Guanli Hou","Seunghun Lee","Mengqi Guo","Runjia Tan","Zhengyu Wen","Qi Wang","Xiaoyu He","Mingyuan Zhang","Michael Bi Mi"],"date":"2026-11-02","title":"TinyAstral: Transferring Self-Evolving Harnesses to Tiny Generalist Manipulation Agents","upvotes":0,"topics":["VLM Training","Reasoning","Evaluation","Reflection"],"id":"arxiv:2610.41216","abstract":"Robot agents built on vision-language models depend on both the planner and its harness: the tools, feedback, memory, and recovery logic around it. Can improvements to a large teacher's harness be carried into a compact agent with lower inference compute cost? We present TinyAstral, a two-stage approach. We first freeze an open-weight teacher and improve its harness through recursive self-improvement (RSI): frontier LLM agents read the teacher's trajectories and propose harness edits, and each edit is accepted only if it passes a paired statistical test. We then freeze the final harness, collect teacher trajectories with reasoning and failure recovery, and distill a small student that replaces the teacher in the same harness. On RoboTwin, harness evolution raises the teacher's success from 33.4% to 63.6%; the final 4B student reaches 62.8%. Across four harness versions, distilled 4B stud"},{"tags":["LLM Training","Evaluation","RL for LLM"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41616","url":"https://arxiv.org/abs/2610.41616","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41616.pdf","source":"arxiv","authors":["Wutong Xu","Yun Qu","Haiyan Feng","Qi Wang","Xiangyang Ji"],"date":"2026-11-02","title":"What Should LLMs Forget: Reinforcement Unlearning of Knowledge Associations","upvotes":0,"topics":["LLM Training","Evaluation","RL for LLM"],"id":"arxiv:2610.41616","abstract":"Large language models (LLMs) acquire extensive factual knowledge during pre-training, which may include sensitive, private, or copyrighted information, motivating the development of unlearning methods that selectively remove specific knowledge while preserving general capabilities. However, existing approaches typically optimize entire responses without explicitly identifying the knowledge to be forgotten, resulting in coarse and uncontrolled forgetting. To address this, we revisit the forgetting target of LLM unlearning and introduce Knowledge Association (KA), which characterizes the association between a query context and its target knowledge and is instantiated by the corresponding conditional predictive distribution, as the fundamental target of forgetting. Based on KA, we propose Knowledge Association Reinforcement Unlearning (KARU), a unified reinforcement learning framework that "},{"tags":["LLM Training","Reasoning","Evaluation"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41169","url":"https://arxiv.org/abs/2610.41169","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41169.pdf","source":"arxiv","authors":["Alexander Detkov","Dashiel Karish","Matthew Oleynikov","Matt Thomson"],"date":"2026-11-02","title":"ImplicitHop: Evaluating knowledge integration across context and memory","upvotes":0,"topics":["LLM Training","Reasoning","Evaluation"],"id":"arxiv:2610.41169","abstract":"The ability to integrate new information and deduce its consequences is central to learning, understanding, and reasoning in large language models (LLMs). Whether information arrives during training or in-context, models must not only store local facts, but propagate their long-range implications globally. To explore information integration in LLMs, we introduce two complementary natural language benchmarks for large-scale evaluation of deductive reasoning as a function of inference depth. The first is a formal graph benchmark enabling controlled evaluation over a wide range of graph topologies and integration tasks; the second is a knowledge composition benchmark grounded in real-world knowledge graphs. We use these benchmarks to compare knowledge integration from information encoded in context versus information encoded in model weights during pretraining, evaluating a set of open mode"},{"tags":["LLM Training","Reasoning","Evaluation"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41162","url":"https://arxiv.org/abs/2610.41162","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41162.pdf","source":"arxiv","authors":["Feng Chen","Jianguo Huang","Yushan Xiao","Yue Li","Bijun Tang","Xuyu Dong","Xingguo Wang","Feiyang Xie","Jianhui Gu","Dongfeng Cao","Hongda Chen","Yongji Gong","Ruiqi Li","Shuxin Li","Xingji Li","Ruitao Lv","Li Song","Lei Wang","Ye Zhang","Xiaoxu Zhao","Xitao Zheng","Bo An","Zheng Liu"],"date":"2026-11-02","title":"FrontierMat: Benchmarking Language Models at the Frontier of Materials R&D","upvotes":0,"topics":["LLM Training","Reasoning","Evaluation"],"id":"arxiv:2610.41162","abstract":"To accelerate materials discovery, language models must be able to address problems at the research frontier. Yet textbook- and examination-derived benchmarks primarily assess established knowledge, leaving performance on frontier research problems largely untested. We introduce FrontierMat, a benchmark of 330 problems drawn from frontier academic and industrial research in fields including aerospace, semiconductors, embodied intelligence and nuclear fusion. Every problem is validated by leading experimentalists and industry experts in its field. Each problem presents a real study and asks the model to infer a withheld outcome or draw a conclusion from selected experimental evidence. Problems are annotated by functional domain, material system and the scale of the governing mechanism; 130 require cross-scale reasoning. The strongest general-purpose model scores only 53.7%, and on matched"},{"tags":["Post-Training","Alignment","Fine-tuning"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41114","url":"https://arxiv.org/abs/2610.41114","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41114.pdf","source":"arxiv","authors":["Moonwon Choi","Kisung Nam","Seunggeun Lee"],"date":"2026-11-02","title":"Predicting Human-Gain Curves under Local Proxy Optimization from Repeated Ratings","upvotes":0,"topics":["Post-Training","Alignment","Fine-tuning"],"id":"arxiv:2610.41114","abstract":"Optimizing a proxy objective can improve human-perceived quality, but the resulting gain can vary with optimization strength. Average proxy-human correlation alone does not reveal how human-perceived quality changes as optimization strength increases. We propose PACE (Proxy Alignment and Curvature Expansion), a pre-optimization diagnostic that uses repeated human ratings to predict the human-gain curve induced by a fixed proxy. The method models proxy optimization as a KL-regularized exponential tilt. At KL radius $d$, the local gain is approximated by $A\\sqrt{d}+Bd$, where $A$ measures first-order proxy-human alignment and $B$ captures the leading second-order correction along the proxy-optimization path. We estimate $A$ and $B$ from repeated human ratings on calibration items and test the resulting gain-curve prediction on held-out evaluation items. Across SummEval, analysis-eligible W"},{"tags":["LLM Training","Reasoning","Evaluation"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41813","url":"https://arxiv.org/abs/2610.41813","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41813.pdf","source":"arxiv","authors":["Qi Wang","Kang Xu","Chengcheng Wan","Jiangtao Wang"],"date":"2026-11-02","title":"RECAST: REconstruction of Chain-of-Thought via Auditable Structured Traces","upvotes":0,"topics":["LLM Training","Reasoning","Evaluation"],"id":"arxiv:2610.41813","abstract":"Large closed-source reasoning models expose only their final answers. The intermediate reasoning that produces those answers is hidden behind API surfaces, tool-call policies, and safety filters. Existing chain-of-thought (CoT) extraction methods assume a side channel: a visible reasoning field, a scratchpad carried through tool calls, or a signed/encrypted reasoning block. We reproduce three representative state-of-the-art extraction methods and find that, on Claude-Sonnet-5.5 accessed through the standard chat-completions interface, all three return zero CoT tokens. The failure is structural rather than a bug: the reasoning field is absent, named tool selection is rejected, free-text scratchpad arguments are filtered, and no replayable reasoning block is exposed. We therefore take a different route. We present RECAST, a reconstruction-based framework that conditions a decoder on the qu"},{"tags":["Post-Training","Multi-Agent","Evaluation"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41358","url":"https://arxiv.org/abs/2610.41358","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41358.pdf","source":"arxiv","authors":["Fengxian Ji","Jingpu Yang","Fan Zhang","Junhong Liang","Qian Jiang","Yuke Li","Jinri Guo","Rongxin Zhu","Zhuohan Xie"],"date":"2026-11-02","title":"Do Transaction Prices Reflect Visual Preference? A Diagnostic Study with Multimodal Language Models","upvotes":0,"topics":["Post-Training","Multi-Agent","Evaluation"],"id":"arxiv:2610.41358","abstract":"Existing visual preference evaluation relies on costly human annotations or preference reward models, whereas online marketplace transaction prices are readily available and reflect real purchasing behavior, offering potential low-cost supervision. However, transaction prices conflate visual preferences with non-visual factors such as provenance, demand, and competition, making aggregate accuracy insufficient to distinguish model errors, unreliable price signals, and protocol confounds. To address this identifiability challenge, we introduce MarketImage, a diagnostic framework that identifies when transaction prices reflect visual preferences, where they fail, and whether multimodal language models can recover human-supported visual preference signals. MarketImage comprises three components: (i) MarketImageArt, 266 six-image comparison sets with transaction prices and price-blind human r"},{"tags":["Agentic RAG","Agentic Search","Evaluation"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41368","url":"https://arxiv.org/abs/2610.41368","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41368.pdf","source":"arxiv","authors":["Russell Ro","Reza Abbasi-Asl"],"date":"2026-11-02","title":"RECITE: Revising Eligibility Criteria Incorporating Textual Evidence","upvotes":0,"topics":["Agentic RAG","Agentic Search","Evaluation"],"id":"arxiv:2610.41368","abstract":"Overly restrictive eligibility criteria contribute to widespread enrollment failure in clinical trials, yet published recommendations for how specific criteria should be broadened remain disconnected from trial design at scale. We introduce RECITE (Revising Eligibility Criteria Incorporating Textual Evidence), a framework for automated discovery, extraction, and implementation of evidence-based eligibility criteria revisions. RECITE uses protocol amendment documents from ClinicalTrials.gov to construct a dataset of 11,913 curated instances across 5,735 trials, each pairing original criteria with documentary evidence and target revisions. We benchmark fifteen LLM configurations under truncated-to-context-window and retrieval-augmented generation conditions, on a 3,116-instance sample under an LLM-as-judge protocol validated against ten domain experts (judge vs. human quadratic-weighted Co"},{"tags":["Post-Training","Reasoning","RL for LLM"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41225","url":"https://arxiv.org/abs/2610.41225","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41225.pdf","source":"arxiv","authors":["Wenxuan Shi","Yaoyu Zhu","Di Huang","Chongxiao Li","Xiaoyun Zhang","Muxin Song","Yutong Wu","Ziyuan Nan","Pengwei Jin","Tian Zhi","Xishan Zhang","Rui Zhang","Xing Hu","Zidong Du","Qi Guo","Yunji Chen"],"date":"2026-11-02","title":"RTL-Interact: Training EDA-Interactive Models for Multi-Task RTL Design","upvotes":0,"topics":["Post-Training","Reasoning","RL for LLM"],"id":"arxiv:2610.41225","abstract":"Large language models offer a promising route to register-transfer-level (RTL) design, but reliable implementations require checking and revision based on electronic design automation (EDA) tools' feedback. Existing RTL-specialized models often lack learned interaction with such EDA tools or rely on separate generation and repair components. We introduce RTL-Interact, a multi-task post-training framework that trains a single RTL-specialized model to generate RTL, construct task-appropriate EDA checks, and revise implementations using tool feedback. The framework combines automatically constructed multi-task demonstrations with staged supervision from chain-of-thought to tool-integrated reasoning. We further introduce Pattern-Aware Policy Optimization (PAPO) for multi-task reinforcement learning. PAPO augments Group Relative Policy Optimization with correctness-gated rewards that favor co"},{"tags":["LLM Training","Reasoning","Alignment"],"submittedDate":"2026-10-30","arxiv":"https://arxiv.org/abs/2610.41280","url":"https://arxiv.org/abs/2610.41280","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.41280.pdf","source":"arxiv","authors":["MiHyeon Kim","Ji-Eun Han","Eunkyeong Lee","Jeehyun Lim","Hwijung Ryu"],"date":"2026-11-02","title":"SciGraphSelect: Auditable Scientific Data Selection through Knowledge--Reasoning Graphs","upvotes":0,"topics":["LLM Training","Reasoning","Alignment"],"id":"arxiv:2610.41280","abstract":"Scientific data selection is typically driven by relevance or utility scores, providing limited insight into why a document is retained. We introduce SciGraphSelect, a reference-grounded framework for auditable scientific data selection. SciGraphSelect organizes domain-specific knowledge, reusable reasoning operations, and reference-attested relations into a typed knowledge--reasoning graph, then scores candidate documents using concept coverage, relation and path co-support, and directional alignment. To avoid over-interpreting document embeddings, rich relational structure is preserved on the reference side while candidate-side evidence is treated conservatively without assuming relation entailment. By exposing the reference-grounded evidence behind each selection, SciGraphSelect brings traceability to the upstream construction of scientific training corpora and complements downstream "},{"tags":["Reasoning","Planning","Evaluation"],"submittedDate":"2026-10-29","arxiv":"https://arxiv.org/abs/2610.40714","url":"https://arxiv.org/abs/2610.40714","announceDate":"2026-11-02","pdf":"https://arxiv.org/pdf/2610.40714.pdf","source":"arxiv","authors":["Robin Staab","Tom Wollschläger","Vahab Mirrokni","Reza Shokri"],"date":"2026-11-02","title":"PrivacyFlow: Privacy in AI Agents through Information Flow Analysis and Consequence-Aware Risk Management","upvotes":0,"topics":["Reasoning","Planning","Evaluation"],"id":"arxiv:2610.40714","abstract":"Autonomous LLM agents executing multi-step workflows over personal data often misalign with user privacy expectations and leak sensitive, out-of-context information. Although Contextual Integrity (CI) formalizes this problem, existing benchmarks and defenses rarely operationalize CI for realistic multi-step task sequences in evolving environments. In this work, we first introduce agentic PrivacyBench, a benchmark of 5873 tasks in 986 task sequences with dynamic environment updates and CI-grounded allow-sets for sensitive information. We also introduce PrivacyFlow, a defense that separates deliberative privacy planning (System 2) from task execution (System 1), treating each sharing decision as a structured risk-management problem. Before execution, PrivacyFlow traces the provenance and purpose of each planned data flow, models recipient background knowledge, and simulates what external a"}],"archive":[],"latestPath":"data/latest.json"};
